import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { audit } from "@/lib/rules-engine/audit";
import type { AuditResult, Extraction, Rule } from "@/lib/rules-engine/types";

/**
 * Known-answer fixtures. Each case folder holds
 * extraction.json, rules.json and expected.json. expected.json is written by hand
 * from the fixture, never generated by running the engine.
 */
const FIXTURES_DIR = fileURLToPath(new URL("./__fixtures__", import.meta.url));

function readJson<T>(path: string): T {
  return JSON.parse(readFileSync(path, "utf8")) as T;
}

const cases = readdirSync(FIXTURES_DIR)
  .filter((jurisdiction) => statSync(join(FIXTURES_DIR, jurisdiction)).isDirectory())
  .flatMap((jurisdiction) =>
    readdirSync(join(FIXTURES_DIR, jurisdiction)).map((name) => ({
      name: `${jurisdiction}/${name}`,
      dir: join(FIXTURES_DIR, jurisdiction, name),
    })),
  );

describe("known-answer fixtures", () => {
  it("has at least one fixture", () => {
    expect(cases.length).toBeGreaterThan(0);
  });

  it.each(cases)("$name", ({ dir }) => {
    const extraction = readJson<Extraction>(join(dir, "extraction.json"));
    const rules = readJson<Rule[]>(join(dir, "rules.json"));
    const expected = readJson<AuditResult>(join(dir, "expected.json"));
    expect(audit(extraction, rules)).toEqual(expected);
  });
});
